function batalkanDP(s, statusBaru){
  // DP dibatalkan / dikembalikan: data DP dipindah ke riwayat dpBatal agar status unit sesuai pilihan
  if(s && s.dp && (Number(s.dp.nominal) || s.dp.nama)){ (s.dpBatal = s.dpBatal || []).push(Object.assign({}, s.dp, {dibatalkan: localYMD(), statusBaru: statusBaru})); }
  if(s) delete s.dp;
}
function reconcileSales(){

if(dpObj.nominal > 0 || dpObj.nama){
  if(!dpObj.tanggal) dpObj.tanggal = localYMD();
  if(dpObj.nominal > hargaJual - diskon){ alert('Nominal DP melebihi harga akhir unit'); return; }
  payload.dp = dpObj;
  if(dpObj.nominal > 0 && (status==='Ready' || status==='Booking')) status = 'DP';
} else delete payload.dp;

const keluarDariDP = !!id && item.status === 'DP' && (status === 'Ready' || status === 'Booking');
if(keluarDariDP && (dpObj.nominal > 0 || dpObj.nama)){
  const okBatal = await confirmChange(`Batalkan DP ${payload.id}?`, [[`DP — ${merek} ${payload.tipe}`, rupiah(dpObj.nominal) + (dpObj.nama ? ' · ' + dpObj.nama : ''), 'dibatalkan → ' + status]]);
  if(!okBatal) return;
  payload.dp = dpObj; batalkanDP(payload, status);
} else if(dpObj.nominal > 0 || dpObj.nama){
  if(!dpObj.tanggal) dpObj.tanggal = localYMD();
  if(dpObj.nominal > hargaJual - diskon){ alert('Nominal DP melebihi harga akhir unit'); return; }
  payload.dp = dpObj;
  if(dpObj.nominal > 0 && (status==='Ready' || status==='Booking')) status = 'DP';
} else delete payload.dp;

const ok = await confirmChange(`Pindahkan ${item.id}?`, [[`Status — ${item.merek} ${item.tipe}`, item.status, newStatus]]);
if(!ok){ showToast('Perubahan dibatalkan'); renderStock(c, ta); return; }
item.status = newStatus;

